{"path": "/tmp/sv-4cea0baaf09e48068be563d95915292b/Components/Pages/Board/TaskCard.razor", "file_text": "<div class="task-card border rounded p-3 mb-2 bg-white shadow-sm">
    <h6 class="mb-1">@Task.Title</h6>
    <p class="text-muted small mb-1">@Task.Assignee</p>
    <span class="badge @PriorityClass me-2">@Task.Priority</span>
    <span class="text-muted small">@Task.DueDate.ToString("MMM dd")</span>

    <div class="mt-2 d-flex gap-1">
        @if (CanMoveLeft)
        {
            <button class="btn btn-outline-secondary btn-sm" @onclick="OnMoveLeft">← Move Left</button>
        }
        @if (CanMoveRight)
        {
            <button class="btn btn-outline-secondary btn-sm" @onclick="OnMoveRight">Move Right →</button>
        }
    </div>
</div>

@code {
    [Parameter, EditorRequired] public TaskItem Task { get; set; } = default!;
    [Parameter] public bool CanMoveLeft { get; set; }
    [Parameter] public bool CanMoveRight { get; set; }
    [Parameter] public EventCallback OnMoveLeft { get; set; }
    [Parameter] public EventCallback OnMoveRight { get; set; }

    private string PriorityClass => Task.Priority switch
    {
        "High" => "bg-danger",
        "Medium" => "bg-warning text-dark",
        "Low" => "bg-success",
        _ => "bg-secondary"
    };
}
"}

{"path": "/tmp/sv-4cea0baaf09e48068be563d95915292b/Components/Pages/Board/AddTaskForm.razor", "file_text": "<div class="border rounded p-3 bg-light mt-2">
    <div class="mb-2">
        <input type="text" class="form-control form-control-sm" placeholder="Title" @bind="title" />
    </div>
    <div class="mb-2">
        <input type="text" class="form-control form-control-sm" placeholder="Assignee" @bind="assignee" />
    </div>
    <div class="mb-2">
        <select class="form-select form-select-sm" @bind="priority">
            <option value="">Select Priority</option>
            <option value="High">High</option>
            <option value="Medium">Medium</option>
            <option value="Low">Low</option>
        </select>
    </div>
    <div class="mb-2">
        <input type="date" class="form-control form-control-sm" @bind="dueDate" />
    </div>
    <div class="d-flex gap-1">
        <button class="btn btn-primary btn-sm" @onclick="HandleSave" disabled="@isSaving">Save</button>
        <button class="btn btn-secondary btn-sm" @onclick="OnCancel" disabled="@isSaving">Cancel</button>
    </div>
</div>

@code {
    [Parameter, EditorRequired] public EventCallback<(string Title, string Assignee, string Priority, DateTime DueDate)> OnSave { get; set; }
    [Parameter] public EventCallback OnCancel { get; set; }

    private string title = "";
    private string assignee = "";
    private string priority = "";
    private DateTime dueDate = DateTime.Today.AddDays(7);
    private bool isSaving;

    private async Task HandleSave()
    {
        if (string.IsNullOrWhiteSpace(title) || string.IsNullOrWhiteSpace(assignee) || string.IsNullOrWhiteSpace(priority))
            return;

        isSaving = true;
        await OnSave.InvokeAsync((title, assignee, priority, dueDate));
        isSaving = false;

        title = "";
        assignee = "";
        priority = "";
        dueDate = DateTime.Today.AddDays(7);
    }
}
"}

{"path": "/tmp/sv-4cea0baaf09e48068be563d95915292b/Components/Pages/Board/KanbanColumn.razor", "file_text": "<div class="kanban-column d-flex flex-column border rounded p-3 bg-body-tertiary" style="min-width: 300px; flex: 1;">
    <h5 class="mb-3">@Status <span class="badge bg-secondary">@Tasks.Count</span></h5>

    @foreach (var task in Tasks)
    {
        <TaskCard Task="task"
                  CanMoveLeft="ColumnIndex > 0"
                  CanMoveRight="ColumnIndex < 2"
                  OnMoveLeft="() => OnMoveLeft.InvokeAsync(task.Id)"
                  OnMoveRight="() => OnMoveRight.InvokeAsync(task.Id)" />
    }

    @if (showForm)
    {
        <AddTaskForm OnSave="HandleSave" OnCancel="() => showForm = false" />
    }
    else
    {
        <button class="btn btn-outline-primary btn-sm mt-auto" @onclick="() => showForm = true">+ Add Task</button>
    }
</div>

@code {
    [Parameter, EditorRequired] public string Status { get; set; } = "";
    [Parameter, EditorRequired] public List<TaskItem> Tasks { get; set; } = new();
    [Parameter] public int ColumnIndex { get; set; }
    [Parameter] public EventCallback<int> OnMoveLeft { get; set; }
    [Parameter] public EventCallback<int> OnMoveRight { get; set; }
    [Parameter] public EventCallback<(string Title, string Assignee, string Priority, DateTime DueDate)> OnTaskCreated { get; set; }

    private bool showForm;

    private async Task HandleSave((string Title, string Assignee, string Priority, DateTime DueDate) formData)
    {
        await OnTaskCreated.InvokeAsync(formData);
        showForm = false;
    }
}
"}

{"path": "/tmp/sv-4cea0baaf09e48068be563d95915292b/Components/Pages/Board/BoardStats.razor", "file_text": "<div class="d-flex flex-wrap gap-3 mb-3 p-3 bg-body-tertiary rounded">
    <div class="badge bg-primary fs-6">Total: @Tasks.Count</div>
    <div class="badge bg-secondary fs-6">To Do: @Tasks.Count(t => t.Status == "To Do")</div>
    <div class="badge bg-info text-dark fs-6">In Progress: @Tasks.Count(t => t.Status == "In Progress")</div>
    <div class="badge bg-success fs-6">Done: @Tasks.Count(t => t.Status == "Done")</div>
    <div class="badge bg-danger fs-6">Overdue: @Tasks.Count(t => t.DueDate < DateTime.Today && t.Status != "Done")</div>
</div>

@code {
    [Parameter, EditorRequired] public List<TaskItem> Tasks { get; set; } = new();
}
"}

{"path": "/tmp/sv-4cea0baaf09e48068be563d95915292b/Components/Pages/Board/BoardSearchBar.razor", "file_text": "<div class="mb-3">
    <input type="text"
           class="form-control"
           placeholder="Search tasks by title..."
           value="@SearchText"
           @oninput="HandleInput" />
</div>

@code {
    [Parameter] public string SearchText { get; set; } = "";
    [Parameter] public EventCallback<string> SearchTextChanged { get; set; }

    private async Task HandleInput(ChangeEventArgs e)
    {
        var value = e.Value?.ToString() ?? "";
        await SearchTextChanged.InvokeAsync(value);
    }
}
"}

